14	// In-memory stand-in for the agency's Postgres. Latencies mirror what the
15	// production database reports for the same queries on a busy workspace.
16	
17	type Store = {
18	  workspaces: Workspace[];
19	  users: User[];
20	  leads: Lead[];
21	  audit: AuditEntry[];
22	  nextLeadNumber: number;
23	};
24	
25	const LATENCY_MS = {
26	  getUserBySession: 100,
27	  getWorkspace: 100,
28	  getLeads: 400,
29	  getLeadStats: 1200,
30	  getSourceBreakdown: 400,
31	  getLead: 80,
32	  insertLead: 120,
33	  updateLeadStatus: 80,
34	  deleteLead: 80,
35	  insertAuditEntry: 250,
36	  listUsers: 50,
37	  createSession: 50,
38	} as const;
39	
40	type QueryName = keyof typeof LATENCY_MS;
41	
42	function sleep(ms: number) {
43	  return new Promise((resolve) => setTimeout(resolve, ms));
44	}
45	
46	async function query<T>(name: QueryName, run: () => T): Promise<T> {
47	  console.count(`db:${name}`);
48	  await sleep(LATENCY_MS[name]);
49	  return run();
50	}
51	
52	// ---------------------------------------------------------------------------
53	// Synthetic seed data (deterministic: same leads on every machine and restart)
54	// ---------------------------------------------------------------------------
55	
56	function mulberry32(seed: number) {
57	  let a = seed >>> 0;
58	  return () => {
